$id=(int)($_GET['id']??$_POST['id']??0); $ruta=['titulo'=>'','slug'=>'','descripcion'=>'','imagen_portada'=>'','nivel'=>'principiante','duracion_min_estimada'=>'','responsable'=>'','orden'=>0,'es_empieza_aqui'=>0,'estado'=>'borrador'];
if($id){$s=$conn->prepare('SELECT * FROM rutas_aprendizaje WHERE id=?');$s->bind_param('i',$id);$s->execute();$ruta=$s->get_result()->fetch_assoc()?:$ruta;$s->close();}
$cursos=$conn->query("SELECT id,titulo FROM cursos WHERE activo=1 ORDER BY titulo")->fetch_all(MYSQLI_ASSOC); $eventos=$conn->query("SELECT id,titulo FROM eventos WHERE activo=1 ORDER BY titulo")->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $titulo=trim($_POST['titulo']??'');$slug=trim($_POST['slug']??'');if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$titulo),'-'));$descripcion=trim($_POST['descripcion']??'');$imagen=trim($_POST['imagen_portada']??'');$nivel=$_POST['nivel']??'principiante';$dur=trim($_POST['duracion_min_estimada']??'')!==''?(int)$_POST['duracion_min_estimada']:null;$responsable=trim($_POST['responsable']??'');$orden=(int)($_POST['orden']??0);$empieza=isset($_POST['es_empieza_aqui'])?1:0;$estado=$_POST['estado']==='publicada'?'publicada':'borrador';
 $conn->begin_transaction();try{if($empieza)$conn->query('UPDATE rutas_aprendizaje SET es_empieza_aqui=0');if($id){$s=$conn->prepare('UPDATE rutas_aprendizaje SET titulo=?,slug=?,descripcion=?,imagen_portada=?,nivel=?,duracion_min_estimada=?,responsable=?,orden=?,es_empieza_aqui=?,estado=? WHERE id=?');$s->bind_param('sssssisiisi',$titulo,$slug,$descripcion,$imagen,$nivel,$dur,$responsable,$orden,$empieza,$estado,$id);}else{$s=$conn->prepare('INSERT INTO rutas_aprendizaje(titulo,slug,descripcion,imagen_portada,nivel,duracion_min_estimada,responsable,orden,es_empieza_aqui,estado) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->bind_param('sssssisiis',$titulo,$slug,$descripcion,$imagen,$nivel,$dur,$responsable,$orden,$empieza,$estado);}$s->execute();$id=$id?:$s->insert_id;$s->close();$s=$conn->prepare('DELETE FROM ruta_aprendizaje_items WHERE ruta_id=?');$s->bind_param('i',$id);$s->execute();$s->close();$tipos=$_POST['item_tipo']??[];$ids=$_POST['item_id']??[];$ob=$_POST['item_obligatorio']??[];$intro=$_POST['item_introduccion']??[];$s=$conn->prepare('INSERT INTO ruta_aprendizaje_items(ruta_id,tipo_contenido,contenido_id,orden,obligatorio,introduccion) VALUES(?,?,?,?,?,?)');foreach($tipos as $i=>$t){$cid=(int)($ids[$i]??0);if(!in_array($t,['curso','evento'],true)||!$cid)continue;$ord=$i+1;$obl=isset($ob[$i])?1:0;$txt=trim($intro[$i]??'');$s->bind_param('isiiis',$id,$t,$cid,$ord,$obl,$txt);$s->execute();}$s->close();$conn->commit();if(es_peticion_ajax()){echo json_encode(['success'=>true,'redirect'=>'rutas.php']);exit;}header('Location: rutas.php');exit;}catch(Throwable $e){$conn->rollback();$error=$e->getCode()==1062?'El slug o un contenido está duplicado.':'No se pudo guardar la ruta.';}}
require_once __DIR__.'/../../backend/rutas_aprendizaje.php';$items=$id?ruta_items($conn,$id):[];$pageTitle=$id?'Editar ruta':'Nueva ruta';include __DIR__.'/_header.php';
?>
<h1 class="h4 mb-3"><?=htmlspecialchars($pageTitle)?></h1><?php if(!empty($error)):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<form method="post" data-ajax-form class="row g-3" id="formRuta"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="col-md-8"><label class="form-label">Título</label><input class="form-control" name="titulo" required value="<?=htmlspecialchars($ruta['titulo'])?>"></div><div class="col-md-4"><label class="form-label">Slug</label><input class="form-control" name="slug" value="<?=htmlspecialchars($ruta['slug'])?>"></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" rows="4" name="descripcion"><?=htmlspecialchars($ruta['descripcion'])?></textarea></div><div class="col-md-4"><label class="form-label">Imagen (URL/ruta)</label><input class="form-control" name="imagen_portada" value="<?=htmlspecialchars($ruta['imagen_portada'])?>"></div><div class="col-md-2"><label class="form-label">Nivel</label><select class="form-select" name="nivel"><?php foreach(['principiante','intermedio','avanzado'] as $n):?><option <?=$ruta['nivel']===$n?'selected':''?>><?=$n?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Duración (min)</label><input type="number" class="form-control" name="duracion_min_estimada" value="<?=htmlspecialchars((string)$ruta['duracion_min_estimada'])?>"></div><div class="col-md-2"><label class="form-label">Orden</label><input type="number" class="form-control" name="orden" value="<?=(int)$ruta['orden']?>"></div><div class="col-md-2"><label class="form-label">Estado</label><select class="form-select" name="estado"><option value="borrador">Borrador</option><option value="publicada" <?=$ruta['estado']==='publicada'?'selected':''?>>Publicada</option></select></div><div class="col-md-8"><label class="form-label">Responsable / instructor</label><input class="form-control" name="responsable" value="<?=htmlspecialchars($ruta['responsable'])?>"></div><div class="col-md-4 form-check form-switch mt-5"><input class="form-check-input" type="checkbox" name="es_empieza_aqui" id="empieza" <?=(int)$ruta['es_empieza_aqui']?'checked':''?>><label for="empieza">Usar como ruta “Empieza aquí”</label></div>
<div class="col-12"><div class="d-flex justify-content-between"><h2 class="h5">Contenidos de la ruta</h2><button type="button" id="agregarItem" class="btn btn-sm btn-outline-primary">+ Agregar contenido</button></div><div id="itemsRuta"></div></div><div class="col-12"><button class="btn btn-success">Guardar ruta</button></div></form>
<template id="tplItem"><div class="card p-3 mb-2 ruta-item"><div class="row g-2 align-items-center"><div class="col-md-2"><select class="form-select item-tipo" name="item_tipo[]"><option value="curso">Curso</option><option value="evento">Evento</option></select></div><div class="col-md-4"><select class="form-select item-id" name="item_id[]"></select></div><div class="col-md-3"><input class="form-control" name="item_introduccion[]" placeholder="Introducción opcional"></div><div class="col-md-2 form-check"><input type="checkbox" class="form-check-input item-obligatorio" name="item_obligatorio[]" checked><label>Obligatorio</label></div><div class="col-md-1 d-flex"><button type="button" class="btn btn-sm subir">↑</button><button type="button" class="btn btn-sm bajar">↓</button><button type="button" class="btn btn-sm text-danger quitar">×</button></div></div></div></template>
<script>const datos={curso:<?=json_encode($cursos)?>,evento:<?=json_encode($eventos)?>};const inicial=<?=json_encode($items)?>;const box=document.getElementById('itemsRuta'),tpl=document.getElementById('tplItem');function opciones(f,t,id){f.innerHTML=datos[t].map(x=>`<option value="${x.id}" ${+x.id===+id?'selected':''}>${$('<div>').text(x.titulo).html()}</option>`).join('');}function agregar(x={}){const n=tpl.content.cloneNode(true),r=n.querySelector('.ruta-item'),t=r.querySelector('.item-tipo'),f=r.querySelector('.item-id');t.value=x.tipo_contenido||'curso';opciones(f,t.value,x.contenido_id);r.querySelector('[name="item_introduccion[]"]').value=x.introduccion||'';r.querySelector('.item-obligatorio').checked=x.obligatorio===undefined||+x.obligatorio===1;t.onchange=()=>opciones(f,t.value);r.querySelector('.quitar').onclick=()=>r.remove();r.querySelector('.subir').onclick=()=>{if(r.previousElementSibling)box.insertBefore(r,r.previousElementSibling)};r.querySelector('.bajar').onclick=()=>{if(r.nextElementSibling)box.insertBefore(r.nextElementSibling,r)};box.appendChild(n);}inicial.forEach(agregar);document.getElementById('agregarItem').onclick=()=>agregar();</script>
